"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type PromptTrailProps = {
  lines?: string[];
  className?: string;
  /** ms between characters */
  charDelay?: number;
};

/**
 * Agent prompt trail — lines type in with a glowing caret wake.
 */
function PromptTrail({
  lines = [
    "Scan monorepo compounds…",
    "Compose linked motion blocks…",
    "Ship the portal preview.",
  ],
  className,
  charDelay = 28,
}: PromptTrailProps) {
  const [lineIdx, setLineIdx] = React.useState(0);
  const [chars, setChars] = React.useState(0);

  React.useEffect(() => {
    const line = lines[lineIdx] ?? "";
    if (chars < line.length) {
      const t = window.setTimeout(() => setChars((c) => c + 1), charDelay);
      return () => window.clearTimeout(t);
    }
    const t = window.setTimeout(() => {
      setLineIdx((i) => (i + 1) % lines.length);
      setChars(0);
    }, 1200);
    return () => window.clearTimeout(t);
  }, [chars, lineIdx, lines, charDelay]);

  const shown = (lines[lineIdx] ?? "").slice(0, chars);

  return (
    <div
      className={cn(
        "relative w-full max-w-md overflow-hidden rounded-2xl border border-border bg-card px-4 py-3 shadow-[var(--shadow-soft)]",
        className,
      )}
    >
      <div
        aria-hidden
        className="pointer-events-none absolute inset-y-0 left-0 w-24 bg-gradient-to-r from-primary/15 to-transparent"
        style={{
          transform: `translateX(${Math.min(chars * 7, 220)}px)`,
          transition: "transform 40ms linear",
        }}
      />
      <div className="relative font-mono text-sm tracking-tight text-foreground">
        <span className="text-muted-foreground">› </span>
        {shown}
        <span className="ml-0.5 inline-block h-4 w-[2px] translate-y-0.5 bg-primary shadow-[0_0_12px_var(--color-primary)]" />
      </div>
      <div className="relative mt-2 flex gap-1">
        {lines.map((_, i) => (
          <span
            key={i}
            className={cn(
              "h-1 flex-1 rounded-full",
              i === lineIdx ? "bg-primary" : "bg-muted",
            )}
          />
        ))}
      </div>
    </div>
  );
}

export { PromptTrail };
